const SERMON_RSS_CACHE_KEY = 'red-point.latest-sermon-rss.v1';
function decodeXml(value: string) {
  return value.replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/<[^>]+>/g, '').trim();
}
function xmlTag(xml: string, tag: string) {
  const m = xml.match(new RegExp(`<${tag}[^>]*>([\s\S]*?)</${tag}>`, 'i'));
  return m ? decodeXml(m[1]) : '';
}
function xmlAttr(xml: string, tag: string, attr: string) {
  const m = xml.match(new RegExp(`<${tag}\\b[^>]*\\b${attr}=[\"']([^\"']+)[\"']`, 'i'));
  return m ? decodeXml(m[1]) : '';
}
function extractRssItems(xml: string): RssSermon[] {
  const itemMatches = xml.match(/<item\b[\s\S]*?<\/item>/gi) || [];
  return itemMatches.map((item, index) => {
    const title = xmlTag(item, 'title');
    const description = xmlTag(item, 'description') || null;
    const link = xmlTag(item, 'link') || xmlTag(item, 'guid') || null;
    const guid = xmlTag(item, 'guid') || link || `rss-${index}`;
    const published = xmlTag(item, 'pubDate');
    const enclosure = item.match(/<enclosure\b[^>]*>/i)?.[0] || '';
    const audio = xmlAttr(enclosure, 'enclosure', 'url') || null;
    const publishedDate = published ? new Date(published) : null;
    const titleDate = title.match(/\b(\d{2}\/\d{2}\/\d{4})\b/);
    let preachedAt = publishedDate && !Number.isNaN(publishedDate.getTime()) ? publishedDate.toISOString() : null;
    if (titleDate) {
      const [day, month, year] = titleDate[1].split('/').map(Number);
      const parsed = new Date(Date.UTC(year, month - 1, day, 7, 0, 0));
      if (!Number.isNaN(parsed.getTime())) preachedAt = parsed.toISOString();
    }
    return { id: `rss:${guid}`, rss_guid: guid, title, description, preached_at: preachedAt, youtube_url: link, published: true, source_url: link, source: 'rss' as const, published_at: publishedDate && !Number.isNaN(publishedDate.getTime()) ? publishedDate.toISOString() : null, audio_url: audio };
  }).filter(item => !!item.title);
}
async function fetchSermonRssXml(): Promise<string> {
  // Web browsers cannot fetch the feed directly: the church website sends no CORS headers.
  // On web, proxy through the sermon-rss edge function; native fetches the feed directly.
  if (Platform.OS === 'web' && supabase) {
    const { data, error } = await supabase.functions.invoke('sermon-rss', { body: {} });
    if (error) throw error;
    const xml = (data as any)?.xml;
    if (typeof xml === 'string' && xml.length) return xml;
    throw new Error('RSS proxy unavailable');
  }
  const response = await fetch(church.sermonRss, { headers: { Accept: 'application/rss+xml, application/xml, text/xml' } });
  if (!response.ok) throw new Error(`RSS ${response.status}`);
  return response.text();
}
async function fetchLatestSermonFromRss(): Promise<RssSermon | null> {
  try {
    const xml = await fetchSermonRssXml();
    const items = extractRssItems(xml).sort((a, b) => +new Date(b.published_at || b.preached_at || 0) - +new Date(a.published_at || a.preached_at || 0));
    const latest = items[0] || null;
    if (latest) await AsyncStorage.setItem(SERMON_RSS_CACHE_KEY, JSON.stringify(latest));
    return latest;
  } catch {
    try {
      const cached = await AsyncStorage.getItem(SERMON_RSS_CACHE_KEY);
      return cached ? JSON.parse(cached) as RssSermon : null;
    } catch { return null; }
  }
}



class AppErrorBoundary extends Component<{children: React.ReactNode}, {hasError:boolean}> {
  state={hasError:false};
  static getDerivedStateFromError(){return {hasError:true};}
  componentDidCatch(error:Error){console.error('Red Point Church app error',error);}
  render(){
    if(this.state.hasError) return <SafeAreaView style={styles.safe}><View style={styles.errorScreen}><Text style={styles.errorEyebrow}>RED POINT CHURCH</Text><Text style={styles.heading}>Something went wrong</Text><Text style={styles.intro}>The app hit an unexpected problem. Please try again.</Text><Button label="TRY AGAIN" onPress={()=>this.setState({hasError:false})}/><Text style={styles.errorVersion}>App {APP_VERSION}</Text></View></SafeAreaView>;
    return this.props.children;
  }
}

function formatDate(value: string | null | undefined) {
  if (!value) return '';
  return new Intl.DateTimeFormat('en-ZA', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(value));
}

function DateTimeField({ label, value, onChange, optional=false }: { label:string; value:string; onChange:(v:string)=>void; optional?:boolean }) {
  const initial=value ? new Date(value) : null;
  const [date,setDate]=useState(initial && !Number.isNaN(initial.getTime()) ? `${initial.getFullYear()}-${String(initial.getMonth()+1).padStart(2,'0')}-${String(initial.getDate()).padStart(2,'0')}` : '');
  const [time,setTime]=useState(initial && !Number.isNaN(initial.getTime()) ? `${String(initial.getHours()).padStart(2,'0')}:${String(initial.getMinutes()).padStart(2,'0')}` : '');
  useEffect(()=>{const d=value?new Date(value):null;if(d && !Number.isNaN(d.getTime())){setDate(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`);setTime(`${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`);}else if(!value){setDate('');setTime('');}},[value]);
  const update=(d:string,t:string)=>{setDate(d);setTime(t);if(!d&&!t){onChange('');return;}if(/^\d{4}-\d{2}-\d{2}$/.test(d)&&/^\d{2}:\d{2}$/.test(t)){const x=new Date(`${d}T${t}:00+02:00`);if(!Number.isNaN(x.getTime()))onChange(`${d}T${t}:00+02:00`);}};
  return <View><Text style={styles.label}>{label}{optional?' (optional)':''}</Text><View style={styles.dateTimeRow}><TextInput value={date} onChangeText={v=>update(v,time)} style={[styles.input,styles.dateInput]} placeholder="YYYY-MM-DD" autoCapitalize="none" keyboardType="numbers-and-punctuation"/><TextInput value={time} onChangeText={v=>update(date,v)} style={[styles.input,styles.timeInput]} placeholder="HH:MM" autoCapitalize="none" keyboardType="numbers-and-punctuation"/></View><Text style={styles.fieldHint}>Date: 2026-09-06   Time: 09:00 (South Africa)</Text><View style={styles.timeQuickRow}><Pressable onPress={()=>{const n=new Date();const d=`${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`;update(d,time||'09:00')}} style={styles.timeQuick}><Text style={styles.timeQuickText}>TODAY</Text></Pressable><Pressable onPress={()=>update(date,'09:00')} style={styles.timeQuick}><Text style={styles.timeQuickText}>09:00</Text></Pressable><Pressable onPress={()=>update(date,'17:30')} style={styles.timeQuick}><Text style={styles.timeQuickText}>17:30</Text></Pressable><Pressable onPress={()=>update(date,'19:00')} style={styles.timeQuick}><Text style={styles.timeQuickText}>19:00</Text></Pressable></View></View>;
}

