function Home({ navigate, events, announcements, sermons, config, selectSermon }: { navigate: (s: Screen) => void; events: Event[]; announcements: Announcement[]; sermons: Sermon[]; config: HomeConfig; selectSermon: (s: Sermon) => void }) {
  const now = Date.now();
  const upcoming = events.filter(e => e.published && new Date(e.starts_at).getTime() >= now).sort((a,b) => +new Date(a.starts_at)-+new Date(b.starts_at));
  const next = upcoming[0];
  const latestAnnouncement = announcements
    .filter(a => a.published && (!a.expires_at || new Date(a.expires_at).getTime() > now))
    .sort((a,b) => +new Date(b.published_at) - +new Date(a.published_at))[0];
  const latestSermon = sermons
    .filter(s => s.published)
    .sort((a,b) => +new Date(b.preached_at || 0) - +new Date(a.preached_at || 0))[0];

  const openLatestSermon = () => {
    if (latestSermon) {
      selectSermon(latestSermon);
      navigate('SermonDetail');
    } else {
      navigate('Sermons');
    }
  };

  return <ScrollView contentContainerStyle={styles.content}>
    <Text style={styles.greeting}>{config.greeting || 'Welcome'}</Text>
    <Text style={styles.homeWelcomeTitle}>Welcome to Red Point Church</Text>
    <Text style={styles.homeWelcomeBody}>We’re glad you’re here.</Text>

    <Text style={styles.homeSectionLabel}>LATEST SERMON</Text>
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={latestSermon ? `Open latest sermon ${latestSermon.title}` : 'Open sermons'}
      onPress={openLatestSermon}
      style={({pressed})=>[styles.latestSermonCard, pressed&&styles.pressed]}
    >
      {latestSermon?.image_url ? (
        <Image source={{uri: latestSermon.image_url}} style={styles.latestSermonImage} accessibilityLabel="Latest sermon thumbnail" />
      ) : (
        <View style={styles.latestSermonPlaceholder}>
          <Text style={styles.latestSermonPlaceholderLabel}>LATEST SERMON</Text>
          <Text style={styles.latestSermonPlaceholderIcon}>▶</Text>
        </View>
      )}
      <View style={styles.latestSermonCopy}>
        <Text style={styles.latestSermonTitle}>{latestSermon?.title || 'No sermon published yet'}</Text>
        {latestSermon?.preached_at ? <Text style={styles.latestSermonMeta}>{formatDate(latestSermon.preached_at)}</Text> : null}
        <Text style={styles.latestSermonAction}>{latestSermon ? 'TAP TO WATCH MESSAGE' : 'VIEW SERMONS'}</Text>
      </View>
    </Pressable>

    <Text style={styles.homeSectionLabel}>LATEST UPDATE</Text>
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={latestAnnouncement ? `Read latest update ${latestAnnouncement.title}` : 'Open announcements'}
      onPress={()=>navigate('Announcements')}
      style={({pressed})=>[styles.latestUpdateCard, pressed&&styles.pressed]}
    >
      <Text style={styles.latestUpdateTitle}>{latestAnnouncement?.title || 'No current update'}</Text>
      <Text style={styles.latestUpdateBody}>{latestAnnouncement?.body || 'Church updates and important information will appear here.'}</Text>
      <Text style={styles.latestUpdateAction}>TAP TO READ UPDATES</Text>
    </Pressable>

    <Text style={styles.homeSectionLabel}>THIS SUNDAY</Text>
    <View style={styles.sundayHomeCard}>
      <Text style={styles.sundayHomeTitle}>{next?.title || church.service}</Text>
      <Text style={styles.sundayHomeTime}>{next ? formatDate(next.starts_at) : church.serviceTime}</Text>
      <Text style={styles.sundayHomeAddress}>📍 {next?.location || church.address}</Text>
      <Button label="VIEW SUNDAY DETAILS" secondary onPress={()=>navigate('Sunday')} />
      <Button label="GET DIRECTIONS" onPress={()=>Linking.openURL(`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(next?.location || church.address)}`)} />
    </View>

    <Pressable accessibilityRole="button" accessibilityLabel="Learn what to expect if you are new" onPress={()=>navigate('New')} style={({pressed})=>[styles.homeNewLink,pressed&&styles.pressed]}>
      <Text style={styles.homeNewLinkTitle}>New to Red Point?</Text>
      <Text style={styles.homeNewLinkBody}>Find out what to expect and how to get connected.</Text>
    </Pressable>
  </ScrollView>;
}
function Search({ events, announcements, sermons, navigate, selectEvent, selectSermon }: { events: Event[]; announcements: Announcement[]; sermons: Sermon[]; navigate:(s:Screen)=>void; selectEvent:(e:Event)=>void; selectSermon:(s:Sermon)=>void }) {
  const [query,setQuery]=useState('');
  const q=query.trim().toLowerCase();
  const results=useMemo(()=>{if(!q)return [];const ev=events.filter(e=>e.published&&`${e.title} ${e.description||''} ${e.location||''}`.toLowerCase().includes(q)).map(e=>({kind:'Event',title:e.title,meta:formatDate(e.starts_at),body:e.location||e.description||'',event:e}));const an=announcements.filter(a=>a.published&&`${a.title} ${a.body}`.toLowerCase().includes(q)).map(a=>({kind:'Announcement',title:a.title,meta:formatDate(a.published_at),body:a.body,announcement:a}));const se=sermons.filter(s=>s.published&&`${s.title} ${s.description||''}`.toLowerCase().includes(q)).map(s=>({kind:'Sermon',title:s.title,meta:formatDate(s.preached_at),body:s.description||'Watch this message.',sermon:s}));return [...ev,...an,...se].slice(0,30);},[q,events,announcements,sermons]);
  return <ScrollView contentContainerStyle={styles.content}><Pressable accessibilityRole="button" accessibilityLabel="Go back" hitSlop={8} onPress={()=>navigate('Home')}><Text style={styles.back}>‹ Back</Text></Pressable><Text style={styles.heading}>Search</Text><Text style={styles.intro}>Find sermons, events and announcements in one place.</Text><TextInput value={query} onChangeText={setQuery} style={styles.searchInput} placeholder="Search church information" autoFocus returnKeyType="search"/>{!q?<View style={styles.searchEmpty}><Text style={styles.cardTitle}>What are you looking for?</Text><Text style={styles.cardBody}>Try a sermon title, event, location or announcement.</Text></View>:results.length===0?<View style={styles.searchEmpty}><Text style={styles.cardTitle}>No results</Text><Text style={styles.cardBody}>Try a different word or phrase.</Text></View>:results.map((r:any,i:number)=><Pressable key={`${r.kind}-${r.title}-${i}`} style={styles.searchResult} onPress={()=>r.kind==='Event'?(selectEvent(r.event),navigate('EventDetail')):r.kind==='Sermon'?(selectSermon(r.sermon),navigate('SermonDetail')):navigate('Announcements')}><Text style={styles.searchKind}>{r.kind.toUpperCase()}</Text><Text style={styles.cardTitle}>{r.title}</Text><Text style={styles.searchMeta}>{r.meta}</Text><Text style={styles.cardBody} numberOfLines={3}>{r.body}</Text></Pressable>)}</ScrollView>;
}

function Events({ events, navigate, selectEvent }: { events: Event[]; navigate: (s: Screen) => void; selectEvent:(e:Event)=>void }) {
  const [query,setQuery]=useState('');
  const [range,setRange]=useState<'upcoming'|'month'>('upcoming');
  const now=Date.now(); const monthEnd=new Date(); monthEnd.setMonth(monthEnd.getMonth()+1);
  const base=events.filter(e=>e.published && new Date(e.starts_at).getTime()>=now && (range==='upcoming'||new Date(e.starts_at).getTime()<=monthEnd.getTime())).sort((a,b)=>+new Date(a.starts_at)-+new Date(b.starts_at));
  const filtered=base.filter(e=>`${e.title} ${e.description||''} ${e.location||''}`.toLowerCase().includes(query.trim().toLowerCase()));
  return <ScrollView contentContainerStyle={styles.content}><Text style={styles.heading}>Events</Text><Text style={styles.intro}>What's coming up at Red Point Church.</Text><TextInput value={query} onChangeText={setQuery} style={styles.searchInput} placeholder="Search events" returnKeyType="search" clearButtonMode="while-editing" /><View style={styles.filterRow}><Pressable onPress={()=>setRange('upcoming')} style={[styles.filterButton,range==='upcoming'&&styles.filterButtonSelected]}><Text style={[styles.filterText,range==='upcoming'&&styles.filterTextSelected]}>ALL UPCOMING</Text></Pressable><Pressable onPress={()=>setRange('month')} style={[styles.filterButton,range==='month'&&styles.filterButtonSelected]}><Text style={[styles.filterText,range==='month'&&styles.filterTextSelected]}>NEXT 30 DAYS</Text></Pressable></View>{filtered.length===0?<View style={styles.card}><Text style={styles.cardTitle}>{base.length?'No events found':'No upcoming events'}</Text><Text style={styles.cardBody}>{base.length?'Try a different search.':'Please check back soon for the next church event.'}</Text></View>:filtered.map(e=><Pressable key={e.id} accessibilityRole="button" accessibilityLabel={`Open event ${e.title}`} onPress={()=>{selectEvent(e);navigate('EventDetail')}} style={({pressed})=>[styles.card,pressed&&styles.pressed]}>{e.image_url?<Image source={{uri:e.image_url}} style={styles.mediaImage}/>:null}<Text style={styles.eyebrow}>{formatDate(e.starts_at)}</Text><Text style={styles.cardTitle}>{e.title}</Text>{e.description?<Text style={styles.cardBody}>{e.description}</Text>:null}{e.location?<Text style={styles.location}>{e.location}</Text>:null}<Text style={styles.eventLink}>VIEW DETAILS ›</Text></Pressable>)}</ScrollView>;
}
