  const share=async()=>{try{await Share.share({title:sermon.title,message:`${sermon.title}${sermon.preached_at?`\n${formatDate(sermon.preached_at)}`:''}${sermon.youtube_url?`\n${sermon.youtube_url}`:''}`});}catch{}};
