function Announcements({ announcements }: { announcements: Announcement[] }) {
  announcements=announcements.filter(a=>a.published&&(!a.expires_at||new Date(a.expires_at).getTime()>Date.now()));
  const now=Date.now(); const visible=announcements.filter(a=>a.published&&(!a.expires_at||new Date(a.expires_at).getTime()>now)).sort((a,b)=>Number(!!b.important)-Number(!!a.important)||(+new Date(b.published_at)-+new Date(a.published_at)));
  return <ScrollView contentContainerStyle={styles.content}><Text style={styles.heading}>Announcements</Text><Text style={styles.intro}>Important updates from the church.</Text>{visible.length===0?<View style={styles.card}><Text style={styles.cardTitle}>No announcements</Text><Text style={styles.cardBody}>There are no current church announcements.</Text></View>:visible.map(a=><View key={a.id} style={styles.card}>{a.image_url?<Image source={{uri:a.image_url}} style={styles.mediaImage}/>:null}{a.important?<Text style={styles.eyebrow}>IMPORTANT</Text>:null}<Text style={styles.eyebrow}>{formatDate(a.published_at)}</Text><Text style={styles.cardTitle}>{a.title}</Text><Text style={styles.cardBody}>{a.body}</Text></View>)}</ScrollView>;
}
