    <View style={styles.welcomeCard}><Text style={styles.welcomeNumber}>2</Text><View style={styles.welcomeCopy}><Text style={styles.cardTitle}>Know what to expect</Text><Text style={styles.cardBody}>We gather to worship God, hear the Bible taught, pray and share life together. You don't need to know anyone or know what to do.</Text></View></View>
