function VisitorForm({ navigate }: { navigate: (s: Screen) => void }) {
  const [name,setName]=useState(''); const [contact,setContact]=useState(''); const [message,setMessage]=useState(''); const [busy,setBusy]=useState(false); const [submitted,setSubmitted]=useState(false);
  const submit=async()=>{if(!name.trim()||!contact.trim()){Alert.alert('Please complete the form','Please enter your name and a phone number or email address.');return;}const endpoint=process.env.EXPO_PUBLIC_VISITOR_FUNCTION_URL;if(!endpoint){Alert.alert('Setup required','The visitor form is ready, but the church email service has not been connected yet.');return;}setBusy(true);try{const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.trim(),contact:contact.trim(),message:message.trim()})});if(!r.ok)throw new Error();setSubmitted(true);}catch{Alert.alert('Could not send','Please try again, or contact the church directly.');}finally{setBusy(false);}};
  if(submitted)return <ScrollView contentContainerStyle={styles.content}><Text style={styles.heading}>Thank you</Text><Text style={styles.intro}>We've received your details. Someone from Red Point Church can follow up with you.</Text><View style={styles.card}><Text style={styles.cardTitle}>What would you like to do next?</Text><Button label="ATTEND A SUNDAY SERVICE" secondary onPress={()=>navigate('Sunday')} /><Button label="FIND A LIFE GROUP" secondary onPress={()=>Linking.openURL(`${church.website}/join-a-life-group`)} /></View></ScrollView>;
  return <ScrollView contentContainerStyle={styles.content}><Pressable accessibilityRole="button" accessibilityLabel="Go back to new here" hitSlop={8} onPress={()=>navigate('New')}><Text style={styles.back}>‹ Back</Text></Pressable><Text style={styles.heading}>Visitor Form</Text><Text style={styles.intro}>Just a few details so someone from the church can welcome you.</Text><View style={styles.formCard}><Text style={styles.label}>Name</Text><TextInput value={name} onChangeText={setName} style={styles.input} placeholder="Your name" autoComplete="name" /><Text style={styles.label}>Phone or email</Text><TextInput value={contact} onChangeText={setContact} style={styles.input} placeholder="How can we contact you?" autoCapitalize="none" keyboardType="email-address" /><Text style={styles.label}>Anything you'd like us to know? (optional)</Text><TextInput value={message} onChangeText={setMessage} style={[styles.input,styles.multiline]} placeholder="Optional message" multiline /><Text style={styles.privacy}>By submitting, you are asking the church to contact you about your visit. Please don't include sensitive personal information.</Text><Button label={busy?'SENDING…':'SEND TO THE CHURCH'} onPress={submit} /></View></ScrollView>;
}
function Privacy({ navigate }: { navigate:(s:Screen)=>void }) {
  return <ScrollView contentContainerStyle={styles.content}><Pressable accessibilityRole="button" accessibilityLabel="Go back to more" hitSlop={8} onPress={()=>navigate('More')}><Text style={styles.back}>‹ Back</Text></Pressable><Text style={styles.heading}>Privacy</Text><Text style={styles.intro}>We only collect information you choose to send us, such as details you provide through the visitor form or a device notification token when you enable notifications.</Text><View style={styles.card}><Text style={styles.cardTitle}>Visitor information</Text><Text style={styles.cardBody}>Visitor form details are stored by Red Point Church so someone can respond to your request. Please do not submit passwords, financial information, or other sensitive information through the form.</Text></View><View style={styles.card}><Text style={styles.cardTitle}>Notifications</Text><Text style={styles.cardBody}>If you enable notifications, the app stores a device push token so the church can send church updates. You can disable notifications in your device settings.</Text></View><View style={styles.card}><Text style={styles.cardTitle}>Questions</Text><Text style={styles.cardBody}>For questions about your information, contact Red Point Church through the official website.</Text><Button label="CHURCH WEBSITE" secondary onPress={()=>Linking.openURL(church.website)} /></View></ScrollView>;
}
