function Calendar({ events, navigate, selectEvent }: { events: Event[]; navigate:(s:Screen)=>void; selectEvent:(e:Event)=>void }) {
  const [monthOffset,setMonthOffset]=useState(0);
  const monthStart=useMemo(()=>{const d=new Date();return new Date(d.getFullYear(),d.getMonth()+monthOffset,1);},[monthOffset]);
  const monthLabel=new Intl.DateTimeFormat('en-ZA',{month:'long',year:'numeric'}).format(monthStart);
  const monthEvents=useMemo(()=>events.filter(e=>e.published&&(()=>{const d=new Date(e.starts_at);return d.getFullYear()===monthStart.getFullYear()&&d.getMonth()===monthStart.getMonth();})()).sort((a,b)=>+new Date(a.starts_at)-+new Date(b.starts_at)),[events,monthStart]);
  const grouped=useMemo(()=>{const map:Record<string,Event[]>={};monthEvents.forEach(e=>{const key=new Date(e.starts_at).toISOString().slice(0,10);(map[key] ||= []).push(e);});return Object.entries(map);},[monthEvents]);
  const todayKey=new Date().toISOString().slice(0,10);
  return <ScrollView contentContainerStyle={styles.content}>
    <Pressable accessibilityRole="button" accessibilityLabel="Go back to more" hitSlop={8} onPress={()=>navigate('More')}><Text style={styles.back}>‹ Back</Text></Pressable>
    <Text style={styles.heading}>Church Calendar</Text>
    <Text style={styles.intro}>See what is happening at Red Point Church, all in one place.</Text>
    <View style={styles.calendarNav}><Pressable accessibilityRole="button" accessibilityLabel="Previous month" hitSlop={8} onPress={()=>setMonthOffset(v=>v-1)} style={styles.calendarArrow}><Text style={styles.calendarArrowText}>‹</Text></Pressable><View style={styles.calendarMonth}><Text style={styles.calendarMonthText}>{monthLabel}</Text></View><Pressable accessibilityRole="button" accessibilityLabel="Next month" hitSlop={8} onPress={()=>setMonthOffset(v=>v+1)} style={styles.calendarArrow}><Text style={styles.calendarArrowText}>›</Text></Pressable></View>
    {monthOffset!==0?<Button label="GO TO THIS MONTH" secondary onPress={()=>setMonthOffset(0)} />:null}
    {grouped.length===0?<View style={styles.calendarEmpty}><Text style={styles.cardTitle}>Nothing scheduled yet</Text><Text style={styles.cardBody}>There are no published church events in {monthLabel}. Try another month or check back soon.</Text></View>:grouped.map(([dayKey,dayEvents])=>{const day=new Date(`${dayKey}T12:00:00`);const dayLabel=new Intl.DateTimeFormat('en-ZA',{weekday:'long',day:'numeric',month:'long'}).format(day);return <View key={dayKey} style={styles.calendarDay}><View style={styles.calendarDayHeader}><Text style={styles.calendarDayText}>{dayLabel}</Text>{dayKey===todayKey?<Text style={styles.todayBadge}>TODAY</Text>:null}</View>{dayEvents.map(e=><Pressable key={e.id} accessibilityRole="button" accessibilityLabel={`Open event ${e.title}`} onPress={()=>{selectEvent(e);navigate('EventDetail')}} style={({pressed})=>[styles.calendarEvent,pressed&&styles.pressed]}><Text style={styles.calendarEventTime}>{formatDate(e.starts_at).split(', ').slice(-1)[0]}</Text><Text style={styles.calendarEventTitle}>{e.title}</Text>{e.location?<Text style={styles.calendarEventMeta}>📍 {e.location}</Text>:null}{e.description?<Text style={styles.calendarEventBody} numberOfLines={2}>{e.description}</Text>:null}</Pressable>)}</View>})}
    <Button label="SEE ALL EVENTS" secondary onPress={()=>navigate('Events')} />
  </ScrollView>;
}
function Journey({ navigate, session, events, ministries }: { navigate:(s:Screen)=>void; session:any; events:Event[]; ministries:Ministry[] }) {
  const [requests,setRequests]=useState<any[]>([]); const [busy,setBusy]=useState(false); const [note,setNote]=useState('');
  const next=events.filter(e=>e.published&&new Date(e.starts_at).getTime()>=Date.now()).sort((a,b)=>+new Date(a.starts_at)-+new Date(b.starts_at)).slice(0,2);
  const options=[
    ['sunday','I want to come on Sunday','Know what to expect, where to go and what is happening next.'],
    ['life_group','I want to find a Life Group','Ask the church to help you find a place to belong and grow.'],
    ['serve','I want to explore serving','Tell the church you would like to discover a way to contribute.'],
    ['prayer','I want prayer','Let the church know you would value prayer or connection.'],
    ['baptism','I want to learn about baptism','Ask for information and a conversation about baptism.'],
    ['pastoral_help','I need pastoral help','Request a personal conversation with an appropriate church leader.'],
  ] as const;
  const load=async()=>{if(!supabase||!session)return;const {data}=await supabase!.from('church_next_step_requests').select('id,next_step_key,note,status,created_at,updated_at').eq('user_id',session.user.id).order('created_at',{ascending:false});if(data)setRequests(data);};
  useEffect(()=>{load()},[session]);
  const request=async(key:string)=>{if(!supabase||!session)return;setBusy(true);try{const {error}=await supabase.rpc('church_request_next_step',{p_next_step_key:key,p_note:note.trim()||null});if(error)throw error;setNote('');await load();Alert.alert('Request sent','Your next step is now visible to the church team.');}catch(e:any){Alert.alert('Could not send request',e?.message||'Please try again.');}finally{setBusy(false);}};
  const cancel=async(id:string)=>{if(!supabase)return;const {error}=await supabase.rpc('church_cancel_next_step',{p_request_id:id});if(error)Alert.alert('Could not cancel',error.message);else load();};
  if(!session)return <ScrollView contentContainerStyle={styles.content}><Pressable onPress={()=>navigate('MyChurch')}><Text style={styles.back}>‹ Back</Text></Pressable><Text style={styles.heading}>Your next steps</Text><Text style={styles.intro}>Sign in to save a next step and let the church help you follow through.</Text><Button label="GO TO MY RED POINT" onPress={()=>navigate('MyChurch')}/></ScrollView>;
  return <ScrollView contentContainerStyle={styles.content}><Pressable accessibilityRole="button" accessibilityLabel="Go back to My Red Point" onPress={()=>navigate('MyChurch')}><Text style={styles.back}>‹ Back</Text></Pressable><Text style={styles.eyebrow}>MY RED POINT</Text><Text style={styles.heading}>What is your next step?</Text><Text style={styles.intro}>You don't need to figure church life out by yourself. Choose one thing you'd like help with.</Text>
    <View style={styles.card}><Text style={styles.cardTitle}>A little context</Text><Text style={styles.cardBody}>Optional note for the church team.</Text><TextInput value={note} onChangeText={setNote} style={[styles.input,styles.multiline]} placeholder="Anything you'd like us to know?" multiline maxLength={500}/></View>
    {options.map(([key,title,body])=>{const active=requests.find(r=>r.next_step_key===key&&['requested','in_progress'].includes(r.status));return <View key={key} style={styles.journeyOption}><Text style={styles.cardTitle}>{title}</Text><Text style={styles.cardBody}>{body}</Text>{active?<><Text style={styles.journeyStatus}>REQUESTED · {new Date(active.created_at).toLocaleDateString('en-ZA')}</Text><Pressable onPress={()=>cancel(active.id)}><Text style={styles.actionLink}>CANCEL REQUEST</Text></Pressable></>:<Button label={busy?'PLEASE WAIT…':'I WANT THIS NEXT STEP'} secondary onPress={()=>request(key)}/>}</View>})}
    {next.length?<><Text style={styles.moreGroupTitle}>COMING UP</Text>{next.map(e=><Pressable key={e.id} onPress={()=>navigate('Events')} style={styles.card}><Text style={styles.eyebrow}>UPCOMING</Text><Text style={styles.cardTitle}>{e.title}</Text><Text style={styles.cardBody}>{formatDate(e.starts_at)}{e.location?`\n${e.location}`:''}</Text></Pressable>)}</>:null}
    {ministries.length?<><Text style={styles.moreGroupTitle}>CHURCH LIFE</Text><Text style={styles.cardBody}>You can also explore ministries and find a place to belong, serve and grow.</Text><Button label="EXPLORE CHURCH LIFE" secondary onPress={()=>navigate('Ministries')}/></>:null}
  </ScrollView>;
}

function MyChurch({ navigate, session, events, ministries }: { navigate:(s:Screen)=>void; session:any; events:Event[]; ministries:Ministry[] }) {
  const [mode,setMode]=useState<'signin'|'signup'>('signin');
  const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const [displayName,setDisplayName]=useState('');
  const [busy,setBusy]=useState(false); const [stage,setStage]=useState<'exploring'|'new'|'connected'>('exploring');
  const [lifeGroup,setLifeGroup]=useState(false); const [serve,setServe]=useState(false);
  const upcoming=events.filter(e=>e.published&&new Date(e.starts_at).getTime()>=Date.now()).sort((a,b)=>+new Date(a.starts_at)-+new Date(b.starts_at)).slice(0,3);
  useEffect(()=>{let active=true;const load=async()=>{if(!session||!supabase)return;const {data}=await supabase!.from('church_member_preferences').select('connection_stage,life_group_interest,serving_interest').eq('user_id',session.user.id).maybeSingle();if(active&&data){setStage(data.connection_stage||'exploring');setLifeGroup(!!data.life_group_interest);setServe(!!data.serving_interest);}};load();return()=>{active=false}},[session]);
  const authenticate=async()=>{if(!supabase)return Alert.alert('Setup required','Supabase is not configured.');if(!email.trim()||password.length<6){Alert.alert('Complete your details','Enter an email address and a password of at least 6 characters.');return;}setBusy(true);try{if(mode==='signup'){if(!displayName.trim()){Alert.alert('Your name','Tell us what you would like the church to call you.');return;}const {data,error}=await supabase.auth.signUp({email:email.trim(),password,options:{data:{display_name:displayName.trim()}}});if(error)throw error;if(!data.session)Alert.alert('Check your email','Your account was created. If email confirmation is enabled, confirm your email and then sign in.');else Alert.alert('Welcome','Your Red Point account is ready.');}else{const {error}=await supabase.auth.signInWithPassword({email:email.trim(),password});if(error)throw error;}setPassword('');}catch(e:any){Alert.alert(mode==='signup'?'Could not create account':'Could not sign in',e?.message||'Please try again.');}finally{setBusy(false);}};
  const savePreferences=async()=>{if(!supabase||!session)return;setBusy(true);try{const {error}=await supabase!.from('church_member_preferences').upsert({user_id:session.user.id,connection_stage:stage,life_group_interest:lifeGroup,serving_interest:serve,updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error)throw error;Alert.alert('Saved','Your church connection preferences are updated.');}catch(e:any){Alert.alert('Could not save',e?.message||'Please try again.');}finally{setBusy(false);}};
  if(!session)return <ScrollView contentContainerStyle={styles.content}><Text style={styles.eyebrow}>MY RED POINT</Text><Text style={styles.heading}>{mode==='signin'?'Welcome back.':'Join Red Point.'}</Text><Text style={styles.intro}>{mode==='signin'?'Keep your church life in one place.':'Create a free account so the church can give you a more personal experience. You can still use the app without an account.'}</Text>{mode==='signup'?<TextInput value={displayName} onChangeText={setDisplayName} style={styles.input} placeholder="Your name" autoCapitalize="words"/>:null}<TextInput value={email} onChangeText={setEmail} style={styles.input} placeholder="Email address" keyboardType="email-address" autoCapitalize="none" autoCorrect={false}/><TextInput value={password} onChangeText={setPassword} style={styles.input} placeholder="Password" secureTextEntry autoCapitalize="none"/><Button label={busy?'PLEASE WAIT…':mode==='signin'?'SIGN IN':'CREATE ACCOUNT'} onPress={authenticate}/><Button label={mode==='signin'?'I’M NEW — CREATE AN ACCOUNT':'I ALREADY HAVE AN ACCOUNT'} secondary onPress={()=>setMode(mode==='signin'?'signup':'signin')}/><View style={styles.newCard}><Text style={styles.cardTitle}>Not ready for an account?</Text><Text style={styles.cardBody}>That's completely fine. Explore sermons, events, ministries and everything you need for your first Sunday without signing in.</Text><Button label="EXPLORE CHURCH LIFE" secondary onPress={()=>navigate('Ministries')}/></View><Text style={styles.privacy}>Your account is for your church experience. Staff/admin tools remain protected separately.</Text></ScrollView>;
  return <ScrollView contentContainerStyle={styles.content}><Text style={styles.eyebrow}>MY RED POINT</Text><Text style={styles.heading}>Welcome back.</Text><Text style={styles.intro}>This is your personal doorway into church life — not another admin dashboard.</Text><Button label="CHOOSE MY NEXT STEP" onPress={()=>navigate('Journey')}/><View style={styles.primaryCard}><Text style={styles.eyebrow}>YOUR CONNECTION</Text><Text style={styles.cardTitle}>{stage==='exploring'?'Exploring Red Point':stage==='new'?'Getting connected':'Connected at Red Point'}</Text><Text style={styles.cardBody}>Choose what you want help with. These preferences guide the church experience; they do not automatically declare you a member.</Text><View style={styles.targetRow}>{(['exploring','new','connected'] as const).map(x=><Pressable key={x} onPress={()=>setStage(x)} style={[styles.targetButton,stage===x&&styles.targetButtonSelected]}><Text style={[styles.targetText,stage===x&&styles.targetTextSelected]}>{x==='exploring'?'EXPLORING':x==='new'?'NEW HERE':'CONNECTED'}</Text></Pressable>)}</View><Pressable onPress={()=>setLifeGroup(!lifeGroup)} style={styles.checkboxRow}><View style={[styles.checkbox,lifeGroup&&styles.checkboxChecked]}>{lifeGroup?<Text style={styles.checkboxTick}>✓</Text>:null}</View><Text style={styles.checkboxText}>I'd like help finding a Life Group</Text></Pressable><Pressable onPress={()=>setServe(!serve)} style={styles.checkboxRow}><View style={[styles.checkbox,serve&&styles.checkboxChecked]}>{serve?<Text style={styles.checkboxTick}>✓</Text>:null}</View><Text style={styles.checkboxText}>I'd like to explore serving</Text></Pressable><Button label={busy?'SAVING…':'SAVE MY CHURCH PREFERENCES'} onPress={savePreferences}/></View><Text style={styles.moreGroupTitle}>YOUR NEXT STEPS</Text>{upcoming.length?upcoming.map(e=><Pressable key={e.id} onPress={()=>navigate('Events')} style={({pressed})=>[styles.card,pressed&&styles.pressed]}><Text style={styles.eyebrow}>UPCOMING</Text><Text style={styles.cardTitle}>{e.title}</Text><Text style={styles.cardBody}>{formatDate(e.starts_at)}{e.location?`\n${e.location}`:''}</Text><Text style={styles.eventLink}>VIEW EVENTS ›</Text></Pressable>):<SectionCard title="Nothing upcoming yet" body="The church calendar will appear here when new events are published."/>}<Text style={styles.moreGroupTitle}>FIND YOUR PLACE</Text>{ministries.slice(0,3).map(m=><View key={m.id} style={styles.card}><Text style={styles.eyebrow}>CHURCH LIFE</Text><Text style={styles.cardTitle}>{m.title}</Text>{m.description?<Text style={styles.cardBody} numberOfLines={3}>{m.description}</Text>:null}</View>)}<Button label="EXPLORE ALL CHURCH LIFE" secondary onPress={()=>navigate('Ministries')}/><Button label="SIGN OUT" secondary onPress={()=>supabase?.auth.signOut()}/></ScrollView>;
}

