function Diagnostics({ navigate, events, announcements, sermons, lastUpdated, loadError, partialError, notificationsEnabled, onRefresh, refreshing }: { navigate:(s:Screen)=>void; events:Event[]; announcements:Announcement[]; sermons:Sermon[]; lastUpdated:string|null; loadError:boolean; partialError:boolean; notificationsEnabled:boolean; onRefresh:()=>void; refreshing:boolean }){
  const supabaseReady=!!supabase;
  const projectId=process.env.EXPO_PUBLIC_EAS_PROJECT_ID || Constants.expoConfig?.extra?.eas?.projectId || '';
  const diagnosticText=[`Red Point Church App ${APP_VERSION}`,`Platform: ${Platform.OS}`,`Device: ${Platform.OS === 'ios' ? 'iPhone/iPad' : Platform.OS === 'android' ? 'Android device' : Platform.OS}`,`Supabase: ${supabaseReady?'configured':'not configured'}`,`EAS project: ${projectId?'configured':'not configured'}`,`Notifications: ${notificationsEnabled?'enabled':'not enabled'}`,`Events loaded: ${events.length}`,`Announcements loaded: ${announcements.length}`,`Sermons loaded: ${sermons.length}`,`Last refresh: ${lastUpdated?formatDate(lastUpdated):'none'}`,`Data error: ${loadError?'yes':'no'}`,`Partial data warning: ${partialError?'yes':'no'}`].join('\n');
  return <ScrollView contentContainerStyle={styles.content}><Pressable accessibilityRole="button" accessibilityLabel="Go back to settings" hitSlop={8} onPress={()=>navigate('More')}><Text style={styles.back}>‹ Back</Text></Pressable><Text style={styles.heading}>App Help</Text><Text style={styles.intro}>If something isn't working, these details help church staff diagnose the problem quickly.</Text><View style={styles.card}><Text style={styles.cardTitle}>App status</Text><Text style={styles.diagnosticRow}>Version · {APP_VERSION}</Text><Text style={styles.diagnosticRow}>Device · {Device.deviceName||'Unknown device'}</Text><Text style={styles.diagnosticRow}>Platform · {Platform.OS}</Text><Text style={styles.diagnosticRow}>Church information · {loadError?'Not available':partialError?'Partly available':'Available'}</Text><Text style={styles.diagnosticRow}>Notifications · {notificationsEnabled?'Enabled':'Not enabled'}</Text></View><View style={styles.card}><Text style={styles.cardTitle}>Information received</Text><Text style={styles.diagnosticRow}>Events · {events.length}</Text><Text style={styles.diagnosticRow}>Announcements · {announcements.length}</Text><Text style={styles.diagnosticRow}>Sermons · {sermons.length}</Text><Text style={styles.diagnosticRow}>Last refresh · {lastUpdated?formatDate(lastUpdated):'Not yet'}</Text></View><Button label={refreshing?'REFRESHING…':'REFRESH CHURCH INFORMATION'} onPress={onRefresh}/><View style={styles.newCard}><Text style={styles.cardTitle}>Need help?</Text><Text style={styles.cardBody}>When contacting the church about an app problem, tell us what you were trying to do and what happened. Include your app version ({APP_VERSION}).</Text><Button label="SHARE DIAGNOSTIC DETAILS" secondary onPress={()=>Share.share({message:diagnosticText,title:'Red Point Church App support details'})}/></View><Text style={styles.diagnosticFoot}>These diagnostics do not collect passwords or private account information.</Text><View style={styles.newCard}><Text style={styles.cardTitle}>Release journey</Text><Text style={styles.cardBody}>Use these checks on a real phone before each release.</Text>{['Home loads church information.','Events opens and an event detail can be opened.','Sermons opens and a sermon can be opened or played.','Search returns matching church content.','More opens and Contact, Directions and I’m New work.','Visitor form opens and submits successfully with a test entry.','Notifications are received and tapping one opens the intended screen.','Airplane mode shows a clear connection/retry state, then recovery works after reconnecting.'].map((item,i)=><View key={item} style={styles.sundayCheck}><View style={styles.sundayDot}><Text style={styles.sundayDotText}>{i+1}</Text></View><View style={styles.sundayCheckCopy}><Text style={styles.sundayCheckBody}>{item}</Text></View></View>)}</View></ScrollView>
}

